import React, { useState, useEffect } from "react";
import TaskList from "./components/TaskList";
import api from "./services/api";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskMetrics{
    averageCompletionTime: number;
    averageTimeByPriority: Record<"High" | "Medium" | "Low", number>;
}

const App: React.FC = () => {
    const [tasks, setTasks] = useState<Task[]>([]);
    const [metrics, setMetrics] = useState<TaskMetrics | null>(null);
    const [currentPage, setCurrentPage] = useState(1);
    const pageSize = 10;

    const fetchTasks = async () => {
        try{
            const response = await api.get<Task[]>("/tasks");
            setTasks(response.data);
        }catch(error){
            console.error("Error getting tasks", error);
        }
    };

    const fetchMetrics = async () => {
        try{
            const response = await api.get<TaskMetrics>("/tasks/metrics");
            setMetrics(response.data);
        }catch(error){
            console.error("Error getting metrics", error);
        }
    };

    useEffect(() => {
        fetchTasks();
        fetchMetrics();
    }, []);

    const markTaskAsDone = async (id: number) => {

        try{
            const taskToUpdate = tasks.find((task) => task.id === id);
            if(!taskToUpdate) return;

            if(taskToUpdate.doneFlag){
                await api.put(`/tasks/${id}/undone`);
            }else{
                await api.post(`/tasks/${id}/done`);
            }

            setTasks((prevTasks) =>
                prevTasks.map((task) =>
                    task.id === id ? { ...task, doneFlag: !task.doneFlag } : task
                )
            );

            fetchMetrics();

        }catch(error){
            console.error("Error marking task as done", error);
        }
    };

    return (
        <div>
            <h1>To-Do App</h1>
            <TaskList
                tasks = {tasks}
                markTaskAsDone = {markTaskAsDone}
                onTaskAdded = {fetchTasks}
                onTaskUpdated = {fetchTasks}
                onTaskDeleted = {fetchTasks}
                fetchTasks = {fetchTasks}
                metrics={metrics}
            />
        </div>
    );
};

export default App;
